CREATE TABLE IF NOT EXISTS projects (id UUID PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id), objective TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals (id UUID PRIMARY KEY, aggregate_type TEXT NOT NULL, aggregate_id UUID NOT NULL, status TEXT NOT NULL, requested_by TEXT NOT NULL, decided_by TEXT, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), decided_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS routing_decisions (id UUID PRIMARY KEY, request_id TEXT NOT NULL, task_class TEXT NOT NULL, policy_mode TEXT NOT NULL, winner_model_id TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commerce_offer_snapshots (id UUID PRIMARY KEY, product_id TEXT NOT NULL, offer_id TEXT NOT NULL, seller_id TEXT NOT NULL, captured_at TIMESTAMPTZ NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS publications (id UUID PRIMARY KEY, master_content_id UUID NOT NULL, workspace_id TEXT NOT NULL, platform TEXT NOT NULL, status TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS outbox_events (id UUID PRIMARY KEY, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, event_type TEXT NOT NULL, payload JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_outbox_unpublished ON outbox_events (occurred_at) WHERE published_at IS NULL;
CREATE TABLE IF NOT EXISTS authorization_audit_events (id UUID PRIMARY KEY, actor_id TEXT NOT NULL, resource TEXT NOT NULL, action TEXT NOT NULL, permission_id TEXT, required_scope TEXT, risk_class TEXT, decision TEXT NOT NULL, reason TEXT NOT NULL, matched_rule_id TEXT, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytics_sessions (id UUID PRIMARY KEY, started_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytics_clicks (id UUID PRIMARY KEY, session_id UUID NOT NULL REFERENCES analytics_sessions(id), campaign_id UUID NOT NULL REFERENCES campaigns(id), publication_id UUID NOT NULL REFERENCES publications(id), master_content_id UUID NOT NULL, product_id TEXT NOT NULL, offer_id TEXT NOT NULL, clicked_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_analytics_clicks_publication_clicked_at ON analytics_clicks (publication_id, clicked_at);
CREATE INDEX IF NOT EXISTS idx_analytics_clicks_session_clicked_at ON analytics_clicks (session_id, clicked_at);
CREATE TABLE IF NOT EXISTS analytics_order_lines (id UUID PRIMARY KEY, session_id UUID NOT NULL REFERENCES analytics_sessions(id), external_order_id TEXT NOT NULL, external_order_line_id TEXT NOT NULL UNIQUE, product_id TEXT NOT NULL, offer_id TEXT NOT NULL, gmv_minor BIGINT NOT NULL CHECK (gmv_minor >= 0), currency TEXT NOT NULL, ordered_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_analytics_order_lines_session_ordered_at ON analytics_order_lines (session_id, ordered_at);
CREATE TABLE IF NOT EXISTS analytics_attributions (order_line_id UUID PRIMARY KEY REFERENCES analytics_order_lines(id), click_id UUID NOT NULL REFERENCES analytics_clicks(id), attribution_model TEXT NOT NULL CHECK (attribution_model = 'LAST_TRACKED_CLICK'), causality_claim BOOLEAN NOT NULL DEFAULT FALSE CHECK (causality_claim = FALSE), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_analytics_attributions_click_id ON analytics_attributions (click_id);
